<?php get_header();while(have_posts()):the_post(); ?><article class="sf-single"><div class="sf-source"><?php echo esc_html(get_post_meta(get_the_ID(),'sfv3_source',true)); ?> · <?php echo esc_html(get_the_date('Y/m/d H:i')); ?></div><h1><?php the_title(); ?></h1><?php if(has_post_thumbnail())the_post_thumbnail('large'); ?><div class="sf-content"><?php the_content(); ?></div></article><?php endwhile;get_footer(); ?>